int digits(long long x) {
    int d = 0;
    while (x > 0) { d++; x /= 10; }
    return d;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        priority_queue<long long> pa, pb;
        for (int i = 0; i < n; i++) { long long x; cin >> x; pa.push(x); }
        for (int i = 0; i < n; i++) { long long x; cin >> x; pb.push(x); }
        long long ops = 0;
        while (!pa.empty()) {
            long long A = pa.top(), B = pb.top();
            if (A == B) { pa.pop(); pb.pop(); }
            else if (A > B) { pa.pop(); pa.push(digits(A)); ops++; }
            else { pb.pop(); pb.push(digits(B)); ops++; }
        }
        cout << ops << "\n";
    }
}

