int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<long long> a(n);
        long long S = 0;
        for (auto &x : a) { cin >> x; S += x; }
        int best = 1;
        for (int k = 1; k <= n; k++) {
            if (S % k != 0) continue;
            long long target = S / k, cur = 0;
            int cnt = 0;
            bool ok = true;
            for (int i = 0; i < n && ok; i++) {
                cur += a[i];
                if (cur == target * (cnt + 1)) cnt++;
                else if (cur > target * (cnt + 1)) ok = false;
            }
            if (ok && cnt == k) best = max(best, k);
        }
        cout << n - best << "\n";
    }
}

