                char c = s[i];
                if ((c == 'E' && nx > 0) || (c == 'W' && nx < 0)) { nx += (c == 'E') ? -1 : 1; p[i] = 'R'; }
                else if ((c == 'N' && ny > 0) || (c == 'S' && ny < 0)) { ny += (c == 'N') ? -1 : 1; p[i] = 'R'; }
            }
        }
        cout << p << "\n";
    }
