int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        vector<long long> c(n + 1), pre(n + 1, 0);
        vector<int> ones(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            cin >> c[i];
            pre[i] = pre[i - 1] + c[i];
            ones[i] = ones[i - 1] + (c[i] == 1);
        }
        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        vector<vector<long long>> sp(LOG, vector<long long>(n + 1, 0));
        for (int i = 1; i <= n; i++) sp[0][i] = c[i];
        for (int j = 1; j < LOG; j++)
            for (int i = 1; i + (1 << j) - 1 <= n; i++)
                sp[j][i] = min(sp[j - 1][i], sp[j - 1][i + (1 << (j - 1))]);
        while (q--) {
            int l, r;
            cin >> l >> r;
            long long m = r - l + 1, S = pre[r] - pre[l - 1];
            int o = ones[r] - ones[l - 1];
            bool ok;
            if (o > 0) ok = (S - o >= m);
            else {
                int j = 31 - __builtin_clz((unsigned)m);
                long long mn = min(sp[j][l], sp[j][r - (1 << j) + 1]);
                ok = (S - mn >= m);
            }
            cout << (ok ? "YES" : "NO") << "\n";
        }
    }
}

