        int n;
        long long k;
        cin >> n >> k;
        vector<long long> a(n);
        for (auto &x : a) cin >> x;
        long long cntLower = 0, ans = -1;
        for (int i = 0; i < n; i++) {
            long long d = 1;
            for (int j = 0; j < a[i]; j++) d *= 10;
            long long m = k + 1 - cntLower;
            if (m <= 0) break;
            long long R = LLONG_MAX;
            if (i + 1 < n) {
                long long dn = 1;
                for (int j = 0; j < a[i + 1]; j++) dn *= 10;
                R = dn / d;
            }
            if (m <= R - 1) { ans = (m + 1) * d - 1; break; }
            cntLower += R - 1;
        }
        cout << ans << "\n";
    }
}

