#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
ll minArea(ll w, ll h, ll n) {
    ll best = LLONG_MAX;
    for (ll W = w; W <= max(w, n); W++) best = min(best, W * max(h, (n + W - 1) / W));
    return best;
}
void boxOf(const vector<ll>& x, const vector<ll>& y, int skip, ll& w, ll& h) {
    ll a = LLONG_MAX, b = LLONG_MIN, c = LLONG_MAX, d = LLONG_MIN;
    for (int i = 0; i < (int)x.size(); i++) {
        if (i == skip) continue;
        a = min(a, x[i]); b = max(b, x[i]); c = min(c, y[i]); d = max(d, y[i]);
    }
    w = b - a + 1; h = d - c + 1;
}
int main() {
    int t; cin >> t;
    while (t--) {
        int n; cin >> n;
        vector<ll> x(n), y(n);
        for (int i = 0; i < n; i++) cin >> x[i] >> y[i];
        if (n == 1) { cout << 1 << "\n"; continue; }
        ll w, h;
        boxOf(x, y, -1, w, h);
        ll ans = w * h;
        int cand[4] = {0, 0, 0, 0};
        for (int i = 0; i < n; i++) {
            if (x[i] < x[cand[0]]) cand[0] = i;
            if (x[i] > x[cand[1]]) cand[1] = i;
            if (y[i] < y[cand[2]]) cand[2] = i;
            if (y[i] > y[cand[3]]) cand[3] = i;
        }
        for (int k = 0; k < 4; k++) {
            boxOf(x, y, cand[k], w, h);
            ans = min(ans, minArea(w, h, n));
        }
        cout << ans << "\n";
    }
}

